class AuthGuard {
    constructor(router, authService) {
        this.router = router;
        this.authService = authService;
    }
    canActivate(route) {
        const currentUser = this.authService.currentUserValue;
        // Chưa đăng nhập
        if (!currentUser) {
            return this.router.parseUrl('/');
        }
        // Có yêu cầu roles
        if (route.data?.roles) {
            const requiredRoles = route.data.roles;
            // Nếu user.roles là string
            if (typeof currentUser.roles === 'string' && !requiredRoles.includes(currentUser.roles)) {
                return this.router.parseUrl('/');
            }
            // Nếu user.roles là mảng
            if (Array.isArray(currentUser.roles) && !currentUser.roles.some((r) => requiredRoles.includes(r))) {
                return this.router.parseUrl('/');
            }
        }
        return true;
    }
}
