    const urlHash = urlObj?.hash ?? '';
    const isExternalLogin = urlHash !== null && urlHash !== undefined && urlHash !== '' && urlHash.includes('dangnhapsinhvien');
    if (isExternalLogin) {
      const match = urlHash?.match(/dangnhapsinhvien(?:\/(.+))?/);
      if (match !== null && match !== undefined) {
        sessionStorage.setItem('IS_EXTERNAL_LOGIN', 'true');
      }
      const externalParams = match !== null && match !== undefined ? match?.[1] ?? '' : '';
      if (externalParams !== null && externalParams !== undefined && externalParams !== '') {
        sessionStorage.setItem('IS_PARAMS_LOGIN', externalParams ?? '');
      }
    } else {
      const hash = window.location.hash ?? '';
      const [path = '', query = ''] = hash.split('?');
      if (query) {
        const params = new URLSearchParams(query);
        const firstKey = params.keys().next()?.value;
        if (firstKey === 'CurrUser') {
          this.isLoginFirst = false;
          this.loadTrangChu();
          return;
        }
      }
    }
    const initialState = {
      isModal: true,
      isExternalLogin
    };
    this.bsModalRef = this.modalService.show(_common_login_login_component__WEBPACK_IMPORTED_MODULE_0__.LoginComponent, {
      initialState,
      backdrop: 'static',
      keyboard: false,
      ignoreBackdropClick: true,
      animated: false
    });
    this.bsModalRef.content.Modallogin.subscribe(res => {
      if (res.res === 200 && res.data) {
        this.isLoginFirst = JSON.parse(res.data);
        this.loadTrangChu();
      }
    });
