  AddScriptHeader(scriptheader) {
    if (scriptheader) {
      var parts = scriptheader.split('</script>');
      parts.forEach(function (part) {
        if (part.trim() !== '') {
          var srcMatch = part.match(/<script.*?src="(.*?)".*?>/);
          if (srcMatch) {
            var script = document.createElement('script');
            script.async = true;
            script.src = srcMatch[1];
            document.head.appendChild(script);
          } else {
            var scriptBody = part.replace(/<script.*?>/, '');
            var script = document.createElement('script');
            script.text = scriptBody;
            document.head.appendChild(script);
          }
        }
      });
    }
  }
  AddScriptBody(scriptbody) {
    if (scriptbody) {
      var parts = scriptbody.split('</noscript>');
      parts.forEach(function (part) {
        if (part.trim() !== '') {
          if (part.includes('<noscript>')) {
            var noscriptContent = part + '</noscript>';
            var noscriptElement = document.createElement('noscript');
            noscriptElement.innerHTML = noscriptContent;
            document.body.prepend(noscriptElement);
          } else {
            var srcMatch = part.match(/<script.*?src="(.*?)".*?>/);
            if (srcMatch) {
              var script = document.createElement('script');
              script.async = true;
              script.src = srcMatch[1];
              document.body.prepend(script); // Sử dụng prepend thay vì appendChild
            } else {
              var scriptBody = part.replace(/<script.*?>/, '');
              var script = document.createElement('script');
              script.text = scriptBody;
              document.body.prepend(script); // Sử dụng prepend thay vì appendChild
            }
          }
        }
      });
    }
  }
