  AddFileMinhChung(cauhoi = {
    id_cau_hoi: ''
  }) {
    if (!this.isuploadfileminhchung) {
      return;
    }
    let initialState = {};
    initialState = {
      ketquadgrl: this.ketquaDG,
      datacauhoi: {
        ...cauhoi
      },
      idketquadgrl: this.idketquadgrl,
      dsnhomcauhoi: this.dsnhomcauhoi,
      dsfileminhchung: this.dsfileminhchung.filter(w => w.id_cau_hoi == cauhoi.id_cau_hoi),
      IsReadOnly: this.IsReadOnly,
      isuploadfileminhchung: this.isuploadfileminhchung,
      co_duong_dang_file: this.co_duong_dang_file
    };
    const msgModalRef1 = this.modalService_1.show(_upfileminhchung_upfileminhchung_component__WEBPACK_IMPORTED_MODULE_2__.UpfileminhchungComponent, {
      initialState,
      backdrop: false,
      keyboard: false,
      ignoreBackdropClick: false,
      animated: false,
      class: 'modal-xl modal-dialog-centered modal-child'
    });
    this.setupMsgBoxModal(msgModalRef1);
    msgModalRef1?.content?.dsFileUpload?.subscribe(res => {
      if (res.res === 200) {
        if (res?.data?.length > 0) {
          const dsA = [...(this.dsfileminhchung ?? [])];
          const dsB = res.data ?? [];
          const mapIndex = new Map();
          dsA.forEach((a, index) => {
            if (a?.id_ket_qua_file != null) {
              mapIndex.set(a.id_ket_qua_file, index);
            }
          });
          dsB.forEach(b => {
            if (!b || b.id_ket_qua_file == null) {
              return;
            }
            const index = mapIndex.get(b.id_ket_qua_file);
            if (index != null) {
              dsA[index] = {
                ...dsA[index],
                ...b
              };
            } else {
              dsA.push({
                ...b
              });
              mapIndex.set(b.id_ket_qua_file, dsA.length - 1);
            }
          });
          this.dsfileminhchung = dsA;
        }
        if (res?.id_xoa) {
          this.dsfileminhchung = this.dsfileminhchung.filter(d => d && d.id_ket_qua_file !== res.id_xoa);
        }
      }
    });
  }
